/** SPARQL generated from the filters: the query of the current selection, and exact matches for nodes not fully loaded. */
import {
  DATE_LEXICAL,
  NUMBER_LEXICAL,
  formatRangeDay,
  parseRangeValue,
  rangeDaySparql,
  rangeLexicalSparql,
} from "./facet-ranges.ts";
import { facetCombinable, NO_MATCH_VALUE, TYPE_FACET_ID, type FacetModes } from "./graph-facets.ts";
import { intrinsicFacetSparqlFilter } from "./graph-filters.ts";
import { UNTYPED_IRI_TYPE } from "./graph-visuals.ts";
import { sparqlFacetValueToken } from "./rdf-terms.ts";
import { iriToken, scoped, resourceToken, type GraphScope } from "./rdf-vocabulary.ts";
import { BLANK_VALUE_ID, LONG_LITERAL_LENGTH, LONG_LITERAL_VALUE_ID } from "./facet-value-ids.ts";

export type QueryRange = { kind: "number" | "date"; from: string; to: string };

export { BLANK_VALUE_ID } from "./facet-value-ids.ts";

/**
 * Which of the nodes have one of the values, or a value inside the range, for the predicate: the check for nodes
 * whose values were not all loaded (a node with more than the cap). The nodes' VALUES sits inside the scoped
 * pattern, as in the other per-node queries.
 */
export function exactMatchQuery(
  ids: string[],
  predicate: string,
  match: { values: string[] } | { range: QueryRange },
  scope: GraphScope = "default",
) {
  const nodes = [...new Set(ids)].map(resourceToken).join(" ");
  let condition: string;
  if ("range" in match) {
    condition = rangeSparqlFilter("?o", match.range) ?? "";
  } else {
    condition = valuesCondition("?o", match.values);
  }
  return `SELECT DISTINCT ?s WHERE {
 ${scoped(`VALUES ?s { ${nodes} } ?s ${iriToken(predicate)} ?o . ${condition}`, scope)}
}`;
}

/**
 * `variable` is one of the values: VALUES for named values; a FILTER when a merged value is among them, which cannot
 * be named: a blank value stands for "any blank node", a long text for any literal over LONG_LITERAL_LENGTH.
 */
function valuesCondition(variable: string, values: readonly string[]) {
  const tokens = values.map(sparqlFacetValueToken).filter((value): value is string => Boolean(value));
  const merged = [
    ...(values.includes(BLANK_VALUE_ID) ? [`isBlank(${variable})`] : []),
    ...(values.includes(LONG_LITERAL_VALUE_ID)
      ? [`(isLiteral(${variable}) && STRLEN(STR(${variable})) > ${LONG_LITERAL_LENGTH})`]
      : []),
  ];
  if (!merged.length) return tokens.length ? `VALUES ${variable} { ${tokens.join(" ")} }` : "FILTER(false)";
  return `FILTER(${[...merged, ...tokens.map((token) => `sameTerm(${variable}, ${token})`)].join(" || ")})`;
}

/** The values of a filter to check on the server, and whether a node needs all of them (FacetMode). */
export type ExactMatch = { values: string[]; mode?: "any" | "all" } | { range: QueryRange };

/**
 * The queries that check which of the nodes match a filter on the server: one (exactMatchQuery) for a range or for
 * any of the values, and one per value when the node needs all of them; a node matches when every query returns it.
 */
export function exactMatchQueries(ids: string[], predicate: string, match: ExactMatch, scope: GraphScope = "default") {
  if ("range" in match || match.mode !== "all" || match.values.length < 2)
    return [exactMatchQuery(ids, predicate, "range" in match ? match : { values: match.values }, scope)];
  return match.values.map((value) => exactMatchQuery(ids, predicate, { values: [value] }, scope));
}

/** A range filter as SPARQL: numbers compare numerically, dates by their ISO day (so date and dateTime both work). */
export function rangeSparqlFilter(variable: string, range: QueryRange) {
  const from = range.from.trim();
  const to = range.to.trim();
  if (!from && !to) {
    return null;
  }
  const text = rangeLexicalSparql(variable);
  const value = range.kind === "number" ? `<http://www.w3.org/2001/XMLSchema#double>(${text})` : rangeDaySparql(text);
  const conditions = [
    `isLiteral(${variable})`,
    `REGEX(${text}, "^${range.kind === "number" ? NUMBER_LEXICAL : DATE_LEXICAL}$")`,
    range.kind === "number" ? `ABS(${value}) <= 1.7976931348623157e308` : `${value} = ${value}`,
  ];
  for (const [bound, operator] of [[from, ">="], [to, "<="]] as const) {
    const parsed = parseRangeValue(range.kind, bound);
    if (!Number.isFinite(parsed)) {
      continue;
    }
    const token = range.kind === "number"
      ? `"${parsed}"^^<http://www.w3.org/2001/XMLSchema#double>`
      : `"${formatRangeDay(parsed)}"^^<http://www.w3.org/2001/XMLSchema#date>`;
    conditions.push(`${value} ${operator} ${token}`);
  }
  return `FILTER(${conditions.join(" && ")})`;
}

export function formatRangeValue(kind: "number" | "date", value: number) {
  if (kind === "date") {
    return formatRangeDay(value);
  }
  return Number.isInteger(value) ? String(value) : String(Number(value.toPrecision(6)));
}

export function generatedFacetQuery(
  selectedFacetValues: Map<string, Set<string>>,
  options: { wikidata: boolean; ranges?: ReadonlyMap<string, QueryRange>; scope?: GraphScope; modes?: FacetModes },
) {
  const scope = options.scope ?? "default";
  // A filter set to "all" with several values (not a range): the node needs each value, so each is asked on its own.
  const needsAll = (facetId: string, values: ReadonlySet<string>) =>
    options.modes?.get(facetId) === "all" && values.size > 1 && facetCombinable(facetId, Boolean(options.ranges?.get(facetId)));
  const activeFacets = [...selectedFacetValues.entries()].filter(
    ([, values]) => values.size > 0,
  );
  const lines: string[] = [];
  let index = 0;
  activeFacets.forEach(([facetId, values]) => {
    const intrinsicFilter = intrinsicFacetSparqlFilter(
      facetId,
      values,
    );
    if (intrinsicFilter) {
      lines.push(`  ${intrinsicFilter}`);
      return;
    }
    const relation =
      facetId === TYPE_FACET_ID
        ? options.wikidata
          ? "<http://www.wikidata.org/prop/direct/P31>"
          : "<http://www.w3.org/1999/02/22-rdf-syntax-ns#type>"
        : iriToken(facetId);
    if (facetId === TYPE_FACET_ID) {
      const untypedSelected = values.has(UNTYPED_IRI_TYPE.id);
      const typedTokens = [...values]
        .filter((value) => value !== UNTYPED_IRI_TYPE.id)
        .map(sparqlFacetValueToken)
        .filter((value): value is string => Boolean(value));
      if (needsAll(facetId, values)) {
        // Every type: "No type" next to a type, or a type that cannot be written, leaves nothing to match.
        const each = typedTokens.map((token, position) =>
          `EXISTS { ${scoped(`?focus ${relation} ${token} .`, scope, `__facetType${index}_${position}`)} }`);
        lines.push(`  FILTER(${untypedSelected || typedTokens.length !== values.size ? "false" : each.join(" && ")})`);
        index += 1;
        return;
      }
      const typedVariable = `?facetTypeValue${index}`;
      const typedMatch = typedTokens.length
        ? `EXISTS { ${scoped(`?focus ${relation} ${typedVariable} .`, scope, `__facetType${index}`)} VALUES ${typedVariable} { ${typedTokens.join(" ")} } }`
        : "false";
      const untypedMatch = untypedSelected
        ? `isIRI(?focus) && NOT EXISTS { ${scoped(`?focus ${relation} ?anyType .`, scope, `__facetUntyped${index}`)} }`
        : "false";
      lines.push(`  FILTER(${untypedMatch} || ${typedMatch})`);
      index += 1;
      return;
    }
    if (needsAll(facetId, values)) {
      // One statement per value, each in its own graph; merged values become what they stand for.
      [...values].forEach((value, position) => {
        const each = `?facetValue${index}_${position}`;
        const statement = (object: string) => `  ${scoped(`?focus ${relation} ${object} .`, scope, `__facet${index}_${position}`)}`;
        if (value === BLANK_VALUE_ID) lines.push(statement(each), `  FILTER(isBlank(${each}))`);
        else if (value === LONG_LITERAL_VALUE_ID)
          lines.push(statement(each), `  FILTER(isLiteral(${each}) && STRLEN(STR(${each})) > ${LONG_LITERAL_LENGTH})`);
        else {
          const token = value === NO_MATCH_VALUE ? null : sparqlFacetValueToken(value);
          lines.push(token ? statement(token) : "  FILTER(false)");
        }
      });
      index += 1;
      return;
    }
    const variable = `?facetValue${index}`;
    lines.push(`  ${scoped(`?focus ${relation} ${variable} .`, scope, `__facet${index}`)}`);
    const range = options.ranges?.get(facetId);
    const rangeFilter = range ? rangeSparqlFilter(variable, range) : null;
    if (rangeFilter) {
      lines.push(`  ${rangeFilter}`);
      index += 1;
      return;
    }
    lines.push(`  ${valuesCondition(variable, [...values])}`);
    index += 1;
  });
  if (!activeFacets.length) {
    return `SELECT ?source ?predicate ?target WHERE {\n  ${scoped("?source ?predicate ?target .", scope)}\n}\nLIMIT 300`;
  }
  // BIND cannot read a variable supplied only by a join outside its UNION branch. Each branch binds its own
  // statement first, then applies every facet to the same endpoint, preserving OR within and AND across facets.
  const branch = (endpoint: "source" | "target") => [
    "  {",
    `    ${scoped("?source ?predicate ?target .", scope, `__facetStatement_${endpoint}`)}`,
    `    BIND(?${endpoint} AS ?focus)`,
    ...lines.map((line) => `  ${line}`),
    "  }",
  ].join("\n");
  return [
    "SELECT DISTINCT ?source ?predicate ?target WHERE {",
    branch("source"),
    "  UNION",
    branch("target"),
    "}",
    "LIMIT 300",
  ].join("\n");
}
